import {writeFile} from 'node:fs/promises';
import sharp from 'sharp';

import {centerLogo} from './center-logo.mjs';

// rasterCenterImage() takes PNG bytes, which Metro cannot import from an asset. Embed a small
// copy of the bundled logo instead of decoding the full-size asset in JavaScript on the device.
const png = await sharp(centerLogo.source)
  .resize(centerLogo.size, centerLogo.size)
  .png({compressionLevel: 9})
  .toBuffer();
await writeFile(
  centerLogo.module,
  [
    '// Generated by scripts/generate-center-logo.mjs from assets/qrcodesdk-logo.png. Do not edit.',
    // Matches Prettier's formatting, so regenerating an unchanged logo produces no diff.
    'export const centerLogoPNG =',
    `  '${png.toString('base64')}';`,
    '',
  ].join('\n'),
);
